using System.Reflection;
using System.Text.Json.Serialization;
using Maxx.Api.Autenticacao;
using Maxx.Api.Demonstracao;
using Maxx.Api.Erros;
using Maxx.Api.Feed;
using Maxx.Api.Fotos;
using Maxx.Api.Health;
