builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.MateriasDoAlunoHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.ReivindicarHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.DecidirComprovacaoHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.FilaDeComprovacoesHandler>();
builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.ContestacaoHandler>();
builder.Services.AddScoped<Maxx.Application.Perfil.BuscaDeAlunosHandler>();
builder.Services.AddScoped<Maxx.Application.Ranking.LeituraDoRankingHandler>();
builder.Services.AddScoped<Maxx.Application.Mural.PublicarAvisoHandler>();
builder.Services.AddScoped<Maxx.Application.Mural.MuralHandler>();
builder.Services.AddScoped<Maxx.Application.Notificacoes.NotificacoesHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.AtosSobreOAlunoHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.ConcessaoDiretaHandler>();
builder.Services.AddScoped<Maxx.Application.Instituicao.PurgaDaDemonstracaoHandler>();

var app = builder.Build();

if (isMigrate)
{
    await using var scope = app.Services.CreateAsyncScope();
    await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(CancellationToken.None);
    return 0;
}

if (isSeed)
{
    if (args is not [_, var nomeDoPerfil, ..] || !Enum.TryParse<PerfilDeSeed>(nomeDoPerfil, ignoreCase: true, out var perfil)
        || !Enum.IsDefined(perfil))
    {
        await Console.Error.WriteLineAsync("Uso: Maxx.Api seed <base|demo>");
        return 2;
    }

    await using var scope = app.Services.CreateAsyncScope();
    try
    {
        await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedAsync(perfil, CancellationToken.None);
    }
    catch (SeedException ex)
    {
        // Dado recusado é resposta esperada, não falha do programa: sem pilha no log.
        await Console.Error.WriteLineAsync(ex.Message);
        return 1;
    }

    return 0;
}

if (isAnulacao)
{
    await using var scope = app.Services.CreateAsyncScope();
    return await ComandoDeAnulacao.ExecutarAsync(scope.ServiceProvider, args, Console.Out, Console.Error, CancellationToken.None);
}

// Primeiro de tudo: o IP e o esquema reais vêm do Caddy, e só dele.
app.UseForwardedHeaders();

// Um formato só de erro: ProblemDetails (RFC 9457).
app.UseExceptionHandler();
app.UseStatusCodePages();

app.UseAuthentication();
app.UseAuthorization();

// Origem única (ADR 0001): toda rota da API vive sob /api, e o Caddy não corta o prefixo.
var api = app.MapGroup("/api");
api.MapHealthEndpoints();

// Contrato versionado: só mudanças aditivas. Fechado por padrão: toda rota de /v1 exige
// login, e a pública diz isso com AllowAnonymous. No grupo, e não numa FallbackPolicy,
// porque a fallback vale também para pedido sem endpoint, e rota inexistente tem de
// continuar 404 (as rotas da demonstração desligada respondem igual a ela).
var v1 = api.MapGroup("/v1").RequireAuthorization();
v1.MapEuEndpoints();
v1.MapTermoDeUsoEndpoints();
v1.MapProfessorEndpoints();
v1.MapPremiosEndpoints();
v1.MapUploadEndpoints();
v1.MapPostEndpoints();
v1.MapSocialEndpoints();
v1.MapFeedEndpoints();
v1.MapPerfilEndpoints();
v1.MapEventoEndpoints();
v1.MapComprovacaoEndpoints();
v1.MapContestacaoEndpoints();
v1.MapAvisoEndpoints();
v1.MapNotificacaoEndpoints();
v1.MapRankingEndpoints();
v1.MapInstituicaoEndpoints();
v1.MapGroup("/auth").AllowAnonymous().MapCadastroEndpoints().MapLoginEndpoints().MapRecuperacaoEndpoints();
if (demonstracao)
{
    v1.MapDemonstracaoEndpoints();
}

if (app.Environment.IsDevelopment())
{
    api.MapOpenApi("/openapi/{documentName}.json");
}

await app.RunAsync();
return 0;

